class Solution {
public:
    int numOfPairs(vector<string>& nums, string target) {
        unordered_map<string, int> cnt;
        for (const string& s : nums) cnt[s]++;

        int ans = 0;
        int tLen = target.size();

        for (auto& [s, c] : cnt) {
            int sLen = s.size();
            if (sLen >= tLen) continue;
            if (target.compare(0, sLen, s) != 0) continue;

            string suffix = target.substr(sLen);
            auto it = cnt.find(suffix);
            if (it == cnt.end()) continue;

            if (s == suffix) {
                ans += c * (c - 1);
            } else {
                ans += c * it->second;
            }
        }

        return ans;
    }
};
